\documentclass[11pt]{article}
\usepackage[margin=1in]{geometry}
\usepackage{graphicx}

\title{Precipitation Response of a Mg--Zn--Ca Alloy to Equal-Channel Angular Pressing}
\author{D.~Ferreira and T.~Aldossary}
\date{May 2026}

\begin{document}
\maketitle

\section{Introduction}
Magnesium alloys containing zinc and calcium are candidates for
resorbable implant applications, but their strength remains modest in
the as-cast condition. Severe plastic deformation by equal-channel
angular pressing (ECAP) refines the grain structure and redistributes
the second phase, and the present note reports the precipitation
response of one such alloy after four passes.

\section{Methods}
Billets of the as-cast alloy were machined to 12 mm diameter and
pressed at 473 K through a 120-degree die, route Bc, for four passes.
The complete processing sequence, including the intermediate
homogenisation step, is laid out in the flow sheet below.

\begin{figure}
\centering
\includegraphics[width=0.6\textwidth]{figures/flowchart.pdf}
\caption{Processing route: casting, homogenisation, and four ECAP passes.}
\end{figure}

\section{Results}
The grain structure after four passes is strongly refined, with a
bimodal distribution of fine equiaxed grains surrounding elongated
deformed regions. The distribution of the Ca-rich phase is visible in
the micrograph.

\begin{figure}
\centering
\includegraphics[width=0.55\textwidth]{figures/sem.pdf}
\caption{Backscattered electron micrograph after four passes.}
\end{figure}

Phase identification relied on diffraction. The as-cast pattern shows
the expected Ca2Mg6Zn3 peaks; after pressing, the peaks broaden but no
new phase appears, indicating redistribution of the intermetallic
rather than dissolution.

\begin{figure}
\centering
\includegraphics[width=0.7\textwidth]{figures/xrd.pdf}
\caption{X-ray diffraction patterns before and after pressing.}
\end{figure}

\section{Conclusion}
Four ECAP passes refine the microstructure and redistribute the
Ca-rich phase without forming new intermetallics. Aging treatments
tailored to this redistributed state are the subject of ongoing work.
\end{document}

